-- What 0.9.13 stored for a conversation's files (SQLite and PostgreSQL), written by v0.9.13's own
-- ConversationRepository (append_turn, merge_turn_attachments); tests/test_shipped_file_records.py.
CREATE TABLE conversation_threads ( conversation_id TEXT PRIMARY KEY, team_id TEXT, owner_canonical_user_id TEXT, owner_agent_id TEXT, owner_agent_name TEXT, requester_name TEXT, requester_id TEXT, root_task_id TEXT, latest_task_id TEXT, status TEXT, subject_preview TEXT, created_at TEXT, updated_at TEXT, synopsis_json TEXT, synopsis_markdown TEXT, summarized_through_turn_index INTEGER DEFAULT 0, last_token_estimate INTEGER DEFAULT 0, last_compacted_at TEXT, compaction_version INTEGER DEFAULT 1, compactor_type TEXT, compaction_state_json TEXT );
CREATE INDEX idx_conversation_threads_owner ON conversation_threads(owner_agent_id, updated_at DESC);
CREATE TABLE conversation_task_links ( conversation_id TEXT NOT NULL, task_id TEXT NOT NULL, followup_to_task_id TEXT, turn_index INTEGER NOT NULL, owner_canonical_user_id TEXT, owner_agent_id TEXT, owner_named_agent_type TEXT, requester_name TEXT, requester_id TEXT, requester_type TEXT, correlation_id TEXT, delivery_mode TEXT, delivery_state TEXT, delivery_via TEXT, delivered_at TEXT, task_status TEXT, problem_text TEXT, final_answer_text TEXT, clarification_summary_text TEXT, execution_history_text TEXT, turn_summary_text TEXT, user_request_summary TEXT, assistant_response_summary TEXT, context_summary_text TEXT, artifact_summary_json TEXT, summary_generator TEXT, summary_generated_at TEXT, tool_artifact_manifest_json TEXT, gateway_context_json TEXT, attachments_json TEXT, attachments_recorded INTEGER NOT NULL DEFAULT 0, created_at TEXT, updated_at TEXT, memory_review_status TEXT NOT NULL DEFAULT 'unreviewed', memory_review_job_id TEXT, memory_review_queued_at_utc TEXT, memory_reviewed_at_utc TEXT, memory_reviewed_by_agent_id TEXT, PRIMARY KEY (conversation_id, task_id) );
CREATE INDEX idx_conversation_task_links_conversation_turn ON conversation_task_links(conversation_id, turn_index);
CREATE INDEX idx_conversation_task_links_created ON conversation_task_links(conversation_id, created_at DESC);
CREATE INDEX idx_conversation_task_links_memory_review ON conversation_task_links(conversation_id, memory_review_status, turn_index);
CREATE INDEX idx_conversation_task_links_owner ON conversation_task_links(owner_agent_id, updated_at DESC);
CREATE INDEX idx_conversation_task_links_request_files_unknown ON conversation_task_links(conversation_id, turn_index) WHERE attachments_recorded = 0;
CREATE INDEX idx_conversation_task_links_task_id ON conversation_task_links(task_id);
CREATE INDEX idx_conversation_task_links_updated ON conversation_task_links(conversation_id, updated_at DESC);
